function currentBuild(){return GUIDED_BUILDS.find(x=>x.id===current+'-'+window.getActiveLab())}
function guideBlock(title,content,language='text'){return '<div class="focus-target"><div class="flex"><b>'+title+'</b><button class="btn alt copy-guide" type="button" data-copy="'+language+'">Copy</button></div><pre class="labcode">'+escapeHTML(content)+'</pre></div>'}
function guidedCodePanel(){const g=currentBuild(),lab=BOOTCAMP_LABS.find(x=>x.id===g.id);return '<div class="focus-prose"><div class="eyebrow">BUILD IT IN YOUR OWN EDITOR</div><h2>Follow the implementation</h2><p class="muted">Use VS Code and your terminal, not a live browser runner. The example below is a starting point with TODOs, not a complete submission.</p><div class="focus-target"><b>1. Create this file</b><pre class="labcode">'+escapeHTML(g.file)+'</pre><p class="muted small">'+escapeHTML(g.note)+'</p></div>'+guideBlock('2. Paste and understand this example code',g.code,'code')+guideBlock('3. Setup and start commands',g.setup,'setup')+guideBlock('4. Verify from the terminal',g.check,'check')+'<div class="focus-target"><b>5. Expected result</b><pre class="labcode">'+escapeHTML(g.result)+'</pre><p class="muted small">Illustrative output; your versions, IDs and timings may differ.</p></div><div class="progress-panel"><b>Why you are doing this</b><p class="muted">'+escapeHTML(g.why)+'</p></div><div class="focus-target"><h3>Before moving on</h3><p>'+escapeHTML(lab.done)+'</p><p class="muted small">Make a commit containing the implementation, tests, and a short README describing the results.</p></div></div>'}
function guidedEvidencePanel(){const g=currentBuild();return '<div class="focus-target"><h3>Evidence checklist</h3><p class="muted">Keep your results in your own repository. These are manual review criteria, not automatically verified.</p><ul><li>Source code for <code>'+escapeHTML(g.file)+'</code> and any supporting files.</li><li>A setup command that works from a clean checkout.</li><li>Actual successful and negative test outputs.</li><li>A short explanation of design choices and limitations.</li></ul></div>'}
document.addEventListener('click',e=>{const b=e.target.closest('.copy-guide');if(!b)return;const pre=b.parentElement?.nextElementSibling;if(pre&&pre.tagName==='PRE'&&navigator.clipboard?.writeText){navigator.clipboard.writeText(pre.textContent).then(()=>{b.textContent='Copied ✓';setTimeout(()=>{b.textContent='Copy'},1300)}).catch(()=>{b.textContent='Select text to copy'})}});
